import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type ToolStatusFile = {
  /** The name of the file generated by the tool's execution. */
  name: string;
  /** URL of the file generated by the tool's execution. */
  url: string;
};

export const toolStatusFileSchema: Schema<ToolStatusFile> = s.object<ToolStatusFile>({
  name: s.string(),
  url: s.string(),
});
